begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not p.prosecdef and p.proconfig @> array['search_path=""'],'registration uses invoker rights and fixed path') from pg_proc p where p.oid='public.register_mobile_push_token(uuid,text,text,text,text)'::regprocedure;
select ok(not has_function_privilege('anon','public.register_mobile_push_token(uuid,text,text,text,text)','execute'),'anonymous cannot register through privileged RPC');
select ok(not has_function_privilege('authenticated','public.register_mobile_push_token(uuid,text,text,text,text)','execute'),'authenticated cannot impersonate another owner through RPC');
select ok(has_function_privilege('service_role','public.register_mobile_push_token(uuid,text,text,text,text)','execute'),'service can register');
insert into auth.users(id,email,aud,role,created_at) values
('a9900000-0000-4000-8000-000000000001','registration-a@example.invalid','authenticated','authenticated',now()),
('a9910000-0000-4000-8000-000000000002','registration-b@example.invalid','authenticated','authenticated',now());
set local role service_role;
select throws_ok($$select public.register_mobile_push_token(null,'ExponentPushToken[first]','ios')$$,'22023',null,'reject missing owner');
select throws_ok($$select public.register_mobile_push_token('a9900000-0000-4000-8000-000000000001','invalid','ios')$$,'22023',null,'reject invalid token');
select throws_ok($$select public.register_mobile_push_token('a9900000-0000-4000-8000-000000000001','ExponentPushToken[first]','web')$$,'22023',null,'reject invalid platform');
select throws_ok($$select public.register_mobile_push_token('a9900000-0000-4000-8000-000000000099','ExponentPushToken[first]','ios')$$,'23503',null,'missing owner fails foreign key');
select set_config('audit.registration_id',public.register_mobile_push_token('a9900000-0000-4000-8000-000000000001','ExponentPushToken[first]','ios','device')::text,true);
select is((select count(*)::integer from public.mobile_notification_preferences where user_id='a9900000-0000-4000-8000-000000000001'),1,'first registration initializes preferences');
update public.mobile_notification_preferences set push_enabled=false where user_id='a9900000-0000-4000-8000-000000000001';
select is(public.register_mobile_push_token('a9900000-0000-4000-8000-000000000001','ExponentPushToken[first]','ios','device')::text,current_setting('audit.registration_id'),'re-registration keeps row ID');
select is((select push_enabled from public.mobile_notification_preferences where user_id='a9900000-0000-4000-8000-000000000001'),false,'re-registration keeps paused preference');
select lives_ok($$select public.register_mobile_push_token('a9900000-0000-4000-8000-000000000001','ExponentPushToken[second]','android','device','2.0')$$,'rotate device token');
select is((select count(*)::integer from public.mobile_push_tokens where user_id='a9900000-0000-4000-8000-000000000001' and is_active),1,'rotation leaves one live token');
select is((select is_active from public.mobile_push_tokens where id=current_setting('audit.registration_id')::uuid),false,'previous token retired');
select set_config('audit.retired_at',(select disabled_at::text from public.mobile_push_tokens where id=current_setting('audit.registration_id')::uuid),true);
select lives_ok($$select public.register_mobile_push_token('a9900000-0000-4000-8000-000000000001','ExponentPushToken[third]','ios','device')$$,'rotate again');
select is((select disabled_at::text from public.mobile_push_tokens where id=current_setting('audit.registration_id')::uuid),current_setting('audit.retired_at'),'later rotation preserves original retirement time');
select lives_ok($$select public.register_mobile_push_token('a9910000-0000-4000-8000-000000000002','ExponentPushToken[third]','ios','device')$$,'transfer token to other account');
select is((select user_id from public.mobile_push_tokens where expo_push_token='ExponentPushToken[third]' and is_active),'a9910000-0000-4000-8000-000000000002'::uuid,'new account owns sole live token');
select lives_ok($$select public.register_mobile_push_token('a9910000-0000-4000-8000-000000000002','ExponentPushToken[noDevice]','ios')$$,'allow token without device ID');
select is((select count(*)::integer from public.mobile_push_tokens where user_id='a9910000-0000-4000-8000-000000000002' and is_active),2,'no-device registration does not retire another device');
reset role;
select set_config('request.jwt.claim.sub','a9900000-0000-4000-8000-000000000001',true);
set local role authenticated;
select is((select count(*)::integer from public.mobile_push_tokens where user_id='a9910000-0000-4000-8000-000000000002'),0,'existing RLS hides other owner tokens');
select throws_ok($$select public.register_mobile_push_token('a9910000-0000-4000-8000-000000000002','ExponentPushToken[third]','ios')$$,'42501',null,'actual user role cannot invoke privileged handoff');
reset role;
select * from finish();
rollback;
